// --- TEXTURE SCRIPT: REACTIVE HOLOGRAPHY ---
// Use this script in the Texture dock for an implicit object

// 1. DENSITY comes from the F slider (Constants dock): raise F for a finer
// grid, lower it for a coarser one. max() keeps the grid from collapsing
// if F is left at 0.
float gridDensity = 25.0 * max(F, 0.05);   // slider F

// 2. We create a grid based on the UV coordinates of the surface
// fract() creates the repeated pattern, we subtract 0.5 to center the cell
vec2 grid = fract(uv * gridDensity) - 0.5; 

// 3. We compute the distance from the edges to draw the lines
float lineDist = min(abs(grid.x), abs(grid.y));

// 4. Spessore della linea
float thickness = 0.05 + 0.03;

// 5. We create a soft "Glow" effect at the edges of the line
float glow = smoothstep(thickness + 0.05, thickness, lineDist);

// 6. Color assignment using the variables injected by the engine
// The background uses the secondary color (u_col2), the lines the primary (u_col1) "boosted"
vec3 baseColor = u_col2;                  // Empty space of the grid (Color 2)
vec3 neonColor = u_col1 * 1.5;           // The UI color, made brighter

// 7. We mix the colors according to the glow computation
vec3 finalColor = mix(baseColor, neonColor, glow);

return finalColor;
